'use strict';
(() => {
const $ = (s,root=document)=>root.querySelector(s);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={book:'M4 4h6a3 3 0 0 1 3 3v14a5 5 0 0 0-4-2H4z M20 4h-4a3 3 0 0 0-3 3v14a5 5 0 0 1 4-2h3z',home:'M3 10 12 3l9 7 M5 9v12h5v-7h4v7h5V9',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',code:'m8 6-6 6 6 6 m8-12 6 6-6 6 m-3-15-2 18',network:'M8 3h8v5H8z M2 16h7v5H2z M15 16h7v5h-7z M12 8v4 M5.5 16v-4h13v4',database:'M21 5c0 2-4 3-9 3S3 7 3 5s4-3 9-3 9 1 9 3z M3 5v14c0 2 4 3 9 3s9-1 9-3V5 M3 12c0 2 4 3 9 3s9-1 9-3',check:'m5 12 4 4L19 6',circle:'M21 12a9 9 0 1 1-9-9 M9 11l3 3 8-9',note:'M5 3h14v12l-6 6H5z M13 21v-6h6 M8 7h8 M8 11h5',review:'M3 11a9 9 0 1 1 2 7 M3 5v6h6 M12 7v5l3 2',chart:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',arrow:'M4 12h16 m-6-6 6 6-6 6',left:'M20 12H4 m6-6-6 6 6 6',external:'M14 3h7v7 m0-7-11 11 M10 3H3v18h18v-7',plus:'M12 4v16 M4 12h16',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14z m5-2 6 6',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M4 16v5h16v-5',close:'m5 5 14 14 M19 5 5 19',pin:'m8 3 8 0-1 6 4 4h-6v8l-2-8H5l4-4z',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',edit:'m15 3 6 6-12 12H3v-6z M12 6l6 6',target:'M21 12a9 9 0 1 1-9-9 M17 12a5 5 0 1 1-5-5 M12 12l9-9',flag:'M5 22V3h13l-3 5 3 5H5',copy:'M9 8h12v13H9z M15 8V3H3v13h6',leaf:'M20 3C7 2 2 8 5 15s14 6 15-12z M4 21 16 8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
const icon = name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
const topics=TRACKS.flatMap(track=>track.modules.flatMap(module=>module.topics));
const topicMap=new Map(topics.map(t=>[t.id,t]));
const moduleMap=new Map(TRACKS.flatMap(t=>t.modules.map(m=>[m.id,m])));
const trackMap=new Map(TRACKS.map(t=>[t.id,t]));
const checks=new Set(topics.flatMap(t=>t.parts.map((p,i)=>`${t.id}-p${i}`)));
const problems=[...new Map(topics.flatMap(t=>t.practice.map(p=>[p.id,{...p,topicId:t.id,track:t.track}]))).values()];
const questions=topics.flatMap(t=>[{id:t.id+'-q1',title:t.question,answer:t.answer,topicId:t.id,track:t.track},{id:t.id+'-q2',title:'Explain the worked example in your own words. What assumption or edge case matters?',answer:t.example.explanation,topicId:t.id,track:t.track}]);
const exerciseMap=new Map([...problems,...questions].map(p=>[p.id,p]));
const TEST_MODE=new URLSearchParams(location.search).has('test');
const KEY='commonplace.learning.v1'+(TEST_MODE?'.test':'');
const statuses={new:'Not started',learning:'Learning',completed:'Completed',revisit:'Revisit later'};
const exerciseStatuses={new:'Not attempted',completed:'Completed',issue:'Having an issue',revisit:'Revisit later'};
const colors=['yellow','sage','lavender','blue','peach'];
let saveFailed=false,observedStorage=null,toastTimer,practiceType='problems',trackTab='curriculum',noteDraft=null,returnFocus=null;
let noteRecorded=false;
const blankState=()=>({version:1,topics:{},checks:{},exercises:{},notes:[],activity:{},goal:5,lastTopic:null,updated:new Date().toISOString()});
const isObject=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function validScope(scope){return scope==='workspace'||trackMap.has(scope)||moduleMap.has(scope)||topicMap.has(scope)||checks.has(scope)||exerciseMap.has(scope);}
function validateState(raw){
 if(!isObject(raw)||raw.version!==1)throw new Error('This is not a supported Commonplace backup (version 1).');
 const next=blankState();
 for(const k of ['topics','checks','exercises','activity'])if(!isObject(raw[k]))throw new Error(`The backup has an invalid ${k} section.`);
 for(const [id,v] of Object.entries(raw.topics)){
  if(!topicMap.has(id)||!isObject(v)||!own(statuses,v.status)||typeof v.updated!=='string'||!Number.isFinite(Date.parse(v.updated)))throw new Error('The backup contains an invalid topic record.');
  next.topics[id]={status:v.status,updated:v.updated};
 }
 for(const [id,v] of Object.entries(raw.checks)){if(!checks.has(id)||typeof v!=='boolean')throw new Error('The backup contains an invalid checkpoint.');next.checks[id]=v;}
 for(const [id,v] of Object.entries(raw.exercises)){
  if(!exerciseMap.has(id)||!isObject(v)||!own(exerciseStatuses,v.status)||!Number.isInteger(v.attempts)||v.attempts<0||v.attempts>9999)throw new Error('The backup contains an invalid practice record.');
  next.exercises[id]={status:v.status,attempts:v.attempts};
 }
 if(!Array.isArray(raw.notes)||raw.notes.length>3000)throw new Error('The backup has an invalid notes collection.');
 const noteIds=new Set();
 next.notes=raw.notes.map(n=>{
  if(!isObject(n)||typeof n.id!=='string'||!/^n-[a-zA-Z0-9-]+$/.test(n.id)||noteIds.has(n.id)||!validScope(n.scope)||typeof n.title!=='string'||n.title.length>200||typeof n.body!=='string'||n.body.length>50000||!colors.includes(n.color)||typeof n.pinned!=='boolean'||typeof n.updated!=='string'||!Number.isFinite(Date.parse(n.updated)))throw new Error('The backup contains an invalid note.');
  noteIds.add(n.id);return {id:n.id,scope:n.scope,title:n.title,body:n.body,color:n.color,pinned:n.pinned,updated:n.updated};
 });
 for(const [date,n] of Object.entries(raw.activity)){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||localDate(new Date(date+'T12:00:00'))!==date||!Number.isInteger(n)||n<0||n>1000000)throw new Error('The backup contains invalid activity data.');next.activity[date]=n;
 }
 if(!Number.isInteger(raw.goal)||raw.goal<1||raw.goal>50)throw new Error('The weekly goal must be between 1 and 50 topics.');
 next.goal=raw.goal;next.lastTopic=topicMap.has(raw.lastTopic)?raw.lastTopic:null;
 return next;
}
let state=blankState();
try{const saved=localStorage.getItem(KEY);observedStorage=saved;if(saved)state=validateState(JSON.parse(saved));}catch(error){saveFailed=true;showStorageWarning('Saved data could not be read. Your existing browser data has not been overwritten. Export any visible work before restoring a valid backup. '+error.message);}
function showStorageWarning(message){const el=$('#storage-warning');el.hidden=false;el.textContent=message;}
function save(){
 state.updated=new Date().toISOString();
 if(saveFailed){$('#save-indicator').textContent='Changes are not saved';return false;}
 try{if(localStorage.getItem(KEY)!==observedStorage){saveFailed=true;$('#save-indicator').textContent='Changes are not saved';showStorageWarning('This workspace changed in another tab. Saving is paused to avoid overwriting those changes. Export this tab’s work before refreshing, or restore a backup to choose a version.');return false;}observedStorage=JSON.stringify(state);localStorage.setItem(KEY,observedStorage);$('#save-indicator').textContent='Saved on this browser';return true;}
 catch(error){saveFailed=true;$('#save-indicator').textContent='Changes are not saved';showStorageWarning('Browser storage is unavailable or full. Your current work remains open, but may be lost on refresh. Use Export backup in the sidebar to save it.');return false;}
}
function recordActivity(){const date=localDate();state.activity[date]=(state.activity[date]||0)+1;}
const statusOf=id=>state.topics[id]?.status||'new';
const exerciseOf=id=>state.exercises[id]||{status:'new',attempts:0};
const completed=list=>list.filter(t=>statusOf(t.id)==='completed').length;
const percent=list=>list.length?Math.round(completed(list)/list.length*100):0;
const trackTopics=t=>t.modules.flatMap(m=>m.topics);
const visibleNotes=()=>state.notes.filter(n=>n.title.trim()||n.body.trim());
const checkpointParent=scope=>scope.slice(0,scope.lastIndexOf('-p'));
const sortedNotes=list=>[...list].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updated.localeCompare(a.updated));
function scopeName(scope){
 if(scope==='workspace')return 'My workspace';
 if(trackMap.has(scope))return trackMap.get(scope).title;
 if(moduleMap.has(scope))return moduleMap.get(scope).title;
 if(topicMap.has(scope))return topicMap.get(scope).title;
 if(checks.has(scope)){const id=checkpointParent(scope),i=Number(scope.slice(scope.lastIndexOf('-p')+2));return topicMap.get(id)?.parts[i]?.title||'Checkpoint';}
 return exerciseMap.get(scope)?.title||'My workspace';
}
function scopeTrack(scope){
 if(trackMap.has(scope))return scope;
 if(topicMap.has(scope))return topicMap.get(scope).track;
 if(moduleMap.has(scope))return moduleMap.get(scope).topics[0]?.track;
 if(checks.has(scope))return topicMap.get(checkpointParent(scope))?.track;
 if(exerciseMap.has(scope))return exerciseMap.get(scope).track;
 return '';
}
function scopeRoute(scope){
 if(trackMap.has(scope))return '#track/'+scope;
 if(topicMap.has(scope))return '#topic/'+scope;
 if(moduleMap.has(scope))return '#track/'+scopeTrack(scope);
 if(checks.has(scope))return '#topic/'+checkpointParent(scope);
 if(exerciseMap.has(scope))return '#topic/'+exerciseMap.get(scope).topicId;
 return '#overview';
}
function weekCompleted(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return topics.filter(t=>statusOf(t.id)==='completed'&&new Date(state.topics[t.id].updated)>=d).length;}
function streak(){let count=0;const d=new Date();if(!state.activity[localDate(d)])d.setDate(d.getDate()-1);while(state.activity[localDate(d)]){count++;d.setDate(d.getDate()-1);}return count;}
function revisitCount(){return topics.filter(t=>statusOf(t.id)==='revisit').length+[...exerciseMap.keys()].filter(id=>['issue','revisit'].includes(exerciseOf(id).status)).length;}
const progressBar=(value,color='')=>`<div class="progress ${color}-bar" role="progressbar" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="100" aria-label="Learning progress"><span style="width:${value}%"></span></div>`;
const badge=(status,exercise=false)=>`<span class="badge ${status}">${escapeHTML((exercise?exerciseStatuses:statuses)[status])}</span>`;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function route(){const [path,query='']=(location.hash.slice(1)||'overview').split('?');return {parts:path.split('/'),params:new URLSearchParams(query)};}
function navigate(hash){if(location.hash===hash)render();else location.hash=hash;$('#sidebar').classList.remove('open');}
function sidebar(){
 const {parts}=route();const activeTrack=parts[0]==='track'?parts[1]:parts[0]==='topic'?topicMap.get(parts[1])?.track:'';
 const nav=(id,label,ic,count='')=>`<button class="nav-item ${parts[0]===id?'active':''}" data-nav="#${id}" ${parts[0]===id?'aria-current="page"':''}>${icon(ic)}${label}${count!==''?`<span class="nav-count">${count}</span>`:''}</button>`;
 $('#sidebar').innerHTML=`<a class="brand" href="#overview"><span class="brand-mark">${icon('book')}</span>commonplace<span style="color:#97ab85">.</span></a>
 <div class="workspace-switch"><span class="workspace-avatar">C</span><div><strong>My learning workspace</strong><small>A personal space for big ideas</small></div></div>
 ${nav('overview','Overview','home')}
 <div class="nav-label">MY LEARNING PATHS</div>
 ${TRACKS.map(t=>`<button class="nav-item ${activeTrack===t.id?'active':''}" data-nav="#track/${t.id}" ${activeTrack===t.id?'aria-current="page"':''}><span class="track-dot ${t.color}"></span>${t.short}<span class="nav-count">${percent(trackTopics(t))}%</span></button>`).join('')}
 <div class="nav-label">MY WORKSPACE</div>
 ${nav('practice','Practice lab','code')}${nav('notes','My notes','note',visibleNotes().length||'')}${nav('review','Revisit queue','review',revisitCount()||'')}${nav('library','Books & resources','book')}${nav('progress','My progress','chart')}
 <div class="nav-spacer"></div>
 <div class="sidebar-goal"><div class="row"><span>${icon('target')} Weekly intention</span><button class="icon-button" data-action="goal" aria-label="Edit weekly goal">${icon('edit')}</button></div>${progressBar(Math.min(100,Math.round(weekCompleted()/state.goal*100)))}<small>${weekCompleted()} of ${state.goal} topics completed this week</small></div>
 <button class="nav-item" data-action="export">${icon('download')}Export backup</button><button class="nav-item" data-action="import">${icon('upload')}Restore backup</button>
 <div class="sidebar-footer"><span>Personal · stored locally</span>${icon('leaf')}</div>`;
}
function art(type){const shapes={ai:'<circle cx="70" cy="45" r="29"/><circle cx="70" cy="45" r="18"/><path d="M70 3v22m0 40v22M28 45h22m40 0h22M40 15l17 17m26 26 17 17M40 75l17-17m26-26 17-17"/><circle cx="70" cy="45" r="5"/>',dsa:'<rect x="33" y="16" width="40" height="30" rx="5"/><rect x="73" y="57" width="40" height="30" rx="5"/><path d="M53 46v27h20M52 25l-7 6 7 6m9-12 7 6-7 6M90 64v17m-7-8h15"/>',system:'<rect x="58" y="4" width="37" height="26" rx="5"/><rect x="23" y="66" width="37" height="26" rx="5"/><rect x="90" y="66" width="37" height="26" rx="5"/><path d="M76 30v18H42v18m34-18h32v18"/><circle cx="76" cy="48" r="4"/>',sql:'<ellipse cx="79" cy="20" rx="32" ry="12"/><path d="M47 20v56c0 17 64 17 64 0V20M47 39c0 17 64 17 64 0M47 58c0 17 64 17 64 0"/>'};return `<svg class="card-art" viewBox="0 0 150 105" fill="none" stroke="currentColor" stroke-width="1.1" aria-hidden="true">${shapes[type]}</svg>`;}
function pageHead(title,subtitle,eyebrow='',actions=''){return `<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${escapeHTML(title)}</h1><p>${escapeHTML(subtitle)}</p></div>${actions}</div>`;}
function stats(){const solved=problems.filter(p=>exerciseOf(p.id).status==='completed').length;return `<div class="stats-row"><div class="stat"><div class="stat-label">${icon('circle')}Topics completed</div><div class="stat-value">${completed(topics)}<small>/ ${topics.length}</small></div></div><div class="stat"><div class="stat-label">${icon('code')}Problems solved</div><div class="stat-value">${solved}<small>/ ${problems.length}</small></div></div><div class="stat"><div class="stat-label">${icon('note')}Notes collected</div><div class="stat-value">${visibleNotes().length}<small>little discoveries</small></div></div><div class="stat"><div class="stat-label">${icon('leaf')}Learning streak</div><div class="stat-value">${streak()}<small>${streak()===1?'day':'days'}</small></div></div></div>`;}
function recommended(){const current=topicMap.get(state.lastTopic);return (current&&statusOf(current.id)!=='completed'?current:null)||topics.find(t=>statusOf(t.id)==='learning')||topics.find(t=>statusOf(t.id)!=='completed')||topics[0];}
function overview(){
 const next=recommended();const date=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
 return pageHead('Your learning, connected.','A home for your curiosity. Learn deeply, make connections, and see how far you’ve come.','THE PERSONAL LEARNING WORKSPACE',`<span class="date-chip">${icon('calendar')}${date}</span>`)+
 `<div class="welcome-banner"><svg class="banner-art" viewBox="0 0 70 70" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M11 18c9-2 18 0 24 5 6-5 15-7 24-5v35c-10-2-18 0-24 5-6-5-14-7-24-5z M35 23v35 M17 27c5 0 9 1 12 3m-12 5c5 0 9 1 12 3m12-8c3-2 7-3 12-3m-12 11c3-2 7-3 12-3 M35 4v8 M22 7l4 7 M48 7l-4 7"/></svg><div><h2>Small steps. Lasting understanding.</h2><p>One concept, one question, one “aha” at a time.</p></div><button class="button primary" data-nav="#topic/${next.id}">${state.lastTopic?'Continue learning':'Start learning'}${icon('arrow')}</button></div>`+
 stats()+`<div class="section-heading"><h2>Your learning paths <span class="track-count">4 thoughtfully connected tracks</span></h2><span class="muted" style="font-size:10px">Explore at your own pace</span></div><div class="track-grid">${TRACKS.map(t=>{const list=trackTopics(t);return `<article class="track-card"><div class="card-cover ${t.color}"><span class="cover-icon">${icon(t.icon)}</span><span class="cover-tag">${t.tag}</span>${art(t.id)}</div><div class="card-body"><div class="card-title"><h3>${t.title}</h3><span class="muted">${icon('arrow')}</span></div><p>${t.description}</p><div class="card-progress-meta"><span>${completed(list)} of ${list.length} topics completed</span><span>${percent(list)}%</span></div>${progressBar(percent(list),t.color)}<div class="card-footer"><span>${t.modules.length} modules · ${list.reduce((n,t)=>n+t.parts.length,0)} checkpoints</span><a href="#track/${t.id}" class="button">Explore path ${icon('arrow')}</a></div></div></article>`;}).join('')}</div>
 <div class="lower-grid"><section><div class="section-heading"><h2>A good next step</h2><span class="muted" style="font-size:10px">Keep your momentum</span></div><div class="next-list">${[next,...TRACKS.filter(t=>t.id!==next.track).map(t=>trackTopics(t).find(x=>statusOf(x.id)!=='completed')).filter(Boolean)].slice(0,3).map(t=>{const track=trackMap.get(t.track);return `<div class="next-row"><span class="next-icon ${track.color}">${icon(track.icon)}</span><div class="grow"><strong>${escapeHTML(t.title)}</strong><small>${track.title} · ${t.parts.length} checkpoints</small></div><button class="icon-button" data-nav="#topic/${t.id}" aria-label="Study ${escapeHTML(t.title)}">${icon('arrow')}</button></div>`;}).join('')}</div></section>
 <section class="overview-notes"><div class="section-heading"><h2>A place for your thoughts</h2><button class="button subtle" data-action="new-note" data-scope="workspace">${icon('plus')}Add a note</button></div>${visibleNotes().length?`<div class="notes-grid">${noteCard(sortedNotes(visibleNotes())[0])}</div>`:`<div class="empty-note">${icon('note')}<h3>Capture the little discoveries.</h3><p>An analogy that clicked. A question for later.<br>Your future self will thank you.</p><button class="button subtle" data-action="new-note" data-scope="workspace">Write your first note ${icon('arrow')}</button></div>`}</section></div>`;
}
function noteCard(n){return `<article class="note-card ${n.color}"><div class="note-scope">${n.pinned?icon('pin'):icon('note')}<a href="${scopeRoute(n.scope)}" title="Return to ${escapeHTML(scopeName(n.scope))}">${escapeHTML(scopeName(n.scope).slice(0,100))}</a></div><h3>${escapeHTML(n.title||'Untitled note')}</h3><div class="note-content">${formatNote(n.body)}</div><div class="note-footer"><span>${new Date(n.updated).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span><div><button class="icon-button" data-action="pin-note" data-id="${n.id}" aria-label="${n.pinned?'Unpin':'Pin'} ${escapeHTML(n.title||'note')}">${icon('pin')}</button><button class="icon-button" data-action="edit-note" data-id="${n.id}" aria-label="Edit ${escapeHTML(n.title||'note')}">${icon('edit')}</button></div></div></article>`;}
function formatNote(text){return escapeHTML(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/^[-*] /gm,'• ').replace(/^\[x\] /gm,'☑ ').replace(/^\[ \] /gm,'☐ ');}
function notesSection(scope,heading='Your notes',includeChildren=false){const list=sortedNotes(visibleNotes().filter(n=>n.scope===scope||(includeChildren&&scopeTrack(n.scope)===scope)));return `<section class="lesson-section" id="notes-section"><div class="section-heading"><h2>${heading}<span class="track-count">${list.length}</span></h2><button class="button subtle" data-action="new-note" data-scope="${scope}">${icon('plus')}Add a note</button></div>${list.length?`<div class="notes-grid">${list.map(noteCard).join('')}</div>`:`<div class="focus-note">${icon('note')}<span>Make it yours. Add a takeaway, a question, or a few bullet points.</span><button class="button subtle" data-action="new-note" data-scope="${scope}">Add note</button></div>`}</section>`;}
function sourceCard(key){const b=BOOKS[key],t=trackMap.get(b.track);return `<article class="source-card"><div class="book-spine ${t.color}">${icon('book')}</div><div><h3>${escapeHTML(b.title)}</h3><small>${escapeHTML(b.author)} · ${escapeHTML(b.edition)}</small><p>${escapeHTML(b.coverage)}</p><a href="${b.url}" target="_blank" rel="noopener noreferrer">Open author / publisher resource ${icon('external')}</a></div></article>`;}
function trackPage(t){const list=trackTopics(t);return `<div class="page-icon ${t.color}">${icon(t.icon)}</div>`+pageHead(t.title,t.description,t.tag,`<button class="button" data-action="new-note" data-scope="${t.id}">${icon('plus')}Add section note</button>`)+`<div class="track-summary"><strong>${percent(list)}%</strong><small>${completed(list)} / ${list.length} topics completed</small>${progressBar(percent(list),t.color)}<small>${t.modules.length} modules · ${list.reduce((n,t)=>n+t.parts.length,0)} checkpoints</small></div><div class="tabs">${['curriculum','notes','resources'].map(tab=>`<button class="tab ${trackTab===tab?'active':''}" data-action="track-tab" data-tab="${tab}">${{curriculum:'Learning roadmap',notes:'Section notebook',resources:'Reading companions'}[tab]}</button>`).join('')}</div>${trackTab==='notes'?notesSection(t.id,'Notes across this path',true):trackTab==='resources'?`<div class="sources-grid">${Object.keys(BOOKS).filter(k=>BOOKS[k].track===t.id).map(sourceCard).join('')}</div>`:`<div class="toolbar"><input type="search" id="track-search" aria-label="Filter this learning path" placeholder="Find a topic in this path…"><select id="track-status" aria-label="Filter topics by status"><option value="all">All statuses</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div id="module-list">${moduleList(t)}</div>${notesSection(t.id,'Section notes')}`}`;}
function moduleList(t,query='',filter='all'){let found=0;const result=t.modules.map((m,index)=>{const list=m.topics.filter(x=>(x.title+' '+x.summary+' '+x.parts.map(p=>p.title).join(' ')).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||statusOf(x.id)===filter));found+=list.length;if(!list.length)return '';return `<details class="module" ${index===0||query||filter!=='all'?'open':''}><summary><strong>${escapeHTML(m.title)}</strong><small>${completed(m.topics)} / ${m.topics.length}</small></summary><div class="module-tools"><p>${escapeHTML(m.description)}</p><button class="icon-button" data-action="scope-notes" data-scope="${m.id}" aria-label="Notes for ${escapeHTML(m.title)}">${icon('note')}</button></div>${list.map(x=>`<div class="topic-row"><input class="topic-checkbox" type="checkbox" data-topic-toggle="${x.id}" aria-label="Mark ${escapeHTML(x.title)} complete" ${statusOf(x.id)==='completed'?'checked':''}><a href="#topic/${x.id}">${escapeHTML(x.title)}</a><small>${x.parts.length} checkpoints</small>${badge(statusOf(x.id))}</div>`).join('')}</details>`;}).join('');return found?result:empty('search','No matching topics','Try another phrase or choose a different status.');}
function empty(ic,title,message){return `<div class="empty-state">${icon(ic)}<h3>${escapeHTML(title)}</h3><p>${escapeHTML(message)}</p></div>`;}
function topicPage(t){const track=trackMap.get(t.track),module=moduleMap.get(t.moduleId),list=trackTopics(track),i=list.indexOf(t);return `<div class="page-icon ${track.color}">${icon(track.icon)}</div>`+pageHead(t.title,`${track.title} / ${module.title}`,'ONE IDEA AT A TIME',`<div class="stack"><button class="button" data-action="new-note" data-scope="${t.id}">${icon('note')}Add note</button><button class="button primary" data-action="complete-topic" data-id="${t.id}">${icon('check')}${statusOf(t.id)==='completed'?'Mark as learning':'Mark complete'}</button></div>`)+`<div class="topic-layout"><article class="lesson-body"><p>${escapeHTML(t.summary)}</p><section class="lesson-section" id="concepts"><h2>Break it down</h2>${t.parts.map((p,j)=>`<div class="lesson-part"><div class="part-title"><input class="topic-checkbox" type="checkbox" data-check="${t.id}-p${j}" id="${t.id}-p${j}" ${state.checks[t.id+'-p'+j]?'checked':''}><label for="${t.id}-p${j}">${escapeHTML(p.title)}</label><button class="icon-button" data-action="scope-notes" data-scope="${t.id}-p${j}" aria-label="Notes for ${escapeHTML(p.title)}">${icon('note')}</button></div><p>${escapeHTML(p.detail)}</p></div>`).join('')}<small style="font-size:10px">Check a concept when you understand it. All checkpoints complete the topic; practice is tracked separately.</small></section><section class="lesson-section" id="example"><h2>See it in practice</h2><div class="code-example"><div class="code-head"><span>${t.track==='dsa'?'JAVA · ILLUSTRATIVE SNIPPET':t.track==='sql'?'SQL / PL/SQL / JDBC · ILLUSTRATIVE EXAMPLE':'WORKED EXAMPLE · CONCEPTUAL'}</span><button class="icon-button" data-action="copy-example" data-id="${t.id}" aria-label="Copy worked example">${icon('copy')}</button></div><pre><code>${escapeHTML(t.example.code)}</code></pre></div><p class="example-caption">${escapeHTML(t.example.explanation)}</p></section><section class="lesson-section" id="questions"><h2>Pause & test your understanding</h2><p class="muted" style="font-size:11px">Answer before revealing the explanation. These are self-assessments, with your own status and attempt count.</p>${questions.filter(q=>q.topicId===t.id).map((q,j)=>`<div class="question-card"><h3><span class="muted">0${j+1} / </span>${escapeHTML(q.title)}</h3><details><summary>Reveal explanation</summary><p>${escapeHTML(q.answer)}</p></details>${exerciseControls(q.id)}</div>`).join('')}</section>${t.practice.length?`<section class="lesson-section" id="problems"><div class="section-heading"><h2>Put the pattern to work</h2><span class="muted" style="font-size:10px">Solve in Java on LeetCode</span></div>${problemTable(t.practice)}<div class="notice">Track your work manually here. LeetCode opens separately; submissions and results are not synced automatically.</div></section>`:''}${notesSection(t.id,'Your topic notebook')}<div class="topic-navigation">${i?`<a class="button" href="#topic/${list[i-1].id}">${icon('left')}Previous topic</a>`:`<a class="button" href="#track/${track.id}">${icon('left')}Back to roadmap</a>`}${i<list.length-1?`<a class="button" href="#topic/${list[i+1].id}">Next topic${icon('arrow')}</a>`:`<a class="button" href="#track/${track.id}">Back to roadmap${icon('arrow')}</a>`}</div></article><aside class="topic-rail"><div><div class="rail-label">YOUR PROGRESS</div><label class="status-label" for="topic-status">Learning status</label><select class="full-width" id="topic-status" data-topic-status="${t.id}">${Object.entries(statuses).map(([s,l])=>`<option value="${s}" ${statusOf(t.id)===s?'selected':''}>${l}</option>`).join('')}</select><div class="rail-box"><div class="rail-label">IN THIS TOPIC</div><div class="rail-links"><a href="#concepts" data-scroll="concepts">Break it down</a><a href="#example" data-scroll="example">Worked example</a><a href="#questions" data-scroll="questions">Knowledge checks</a>${t.practice.length?'<a href="#problems" data-scroll="problems">LeetCode practice</a>':''}<a href="#notes-section" data-scroll="notes-section">Your notes</a></div></div></div><div class="rail-box"><div class="rail-label">GO A LITTLE DEEPER</div>${t.sources.map(k=>`<a href="${BOOKS[k].url}" target="_blank" rel="noopener noreferrer">${escapeHTML(BOOKS[k].title)} ↗</a>`).join('')}<p>Original study notes and examples. Use the linked books for the full treatment.</p></div></aside></div>`;}
function exerciseControls(id){const p=exerciseOf(id);return `<div class="practice-controls"><div><label for="status-${id}">Your status</label>${exerciseSelect(id,p)}</div><div><label for="attempt-${id}">Attempts</label>${stepper(id,p.attempts)}</div><button class="button subtle" data-action="scope-notes" data-scope="${id}">${icon('note')}Solution notes</button></div>`;}
function exerciseSelect(id,p){return `<select id="status-${id}" data-exercise="${id}" aria-label="Status for ${escapeHTML(exerciseMap.get(id)?.title||'problem')}">${Object.entries(exerciseStatuses).map(([s,l])=>`<option value="${s}" ${p.status===s?'selected':''}>${l}</option>`).join('')}</select>`;}
function stepper(id,value){return `<div class="attempt-stepper"><button data-action="attempt" data-id="${id}" data-delta="-1" aria-label="Decrease attempts for ${escapeHTML(exerciseMap.get(id)?.title||'problem')}">−</button><input type="number" id="attempt-${id}" data-attempts="${id}" value="${value}" min="0" max="9999" step="1" aria-label="Attempts for ${escapeHTML(exerciseMap.get(id)?.title||'problem')}"><button data-action="attempt" data-id="${id}" data-delta="1" aria-label="Increase attempts for ${escapeHTML(exerciseMap.get(id)?.title||'problem')}">+</button></div>`;}
function problemTable(list,showTopic=false){return `<div class="practice-table-wrap"><table class="practice-table"><thead><tr><th>Problem</th><th>Difficulty</th><th>Your status</th><th>Attempts</th><th>Notes</th></tr></thead><tbody>${list.map(p=>`<tr><td><a href="${p.url}" target="_blank" rel="noopener noreferrer"><span class="problem-number">${p.number}.</span>${escapeHTML(p.title)} ↗</a>${showTopic?`<a class="topic-link" href="#topic/${p.topicId}">${escapeHTML(topicMap.get(p.topicId).title)}</a>`:''}</td><td><span class="badge ${p.difficulty.toLowerCase()}">${p.difficulty}</span></td><td>${exerciseSelect(p.id,exerciseOf(p.id))}</td><td>${stepper(p.id,exerciseOf(p.id).attempts)}</td><td><button class="icon-button" data-action="scope-notes" data-scope="${p.id}" aria-label="Notes for ${escapeHTML(p.title)}">${icon('note')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function practice(){const param=route().params.get('status')||'all';return pageHead('Practice with purpose.','Your working space for problems, attempts, and the lessons hidden in each mistake.','THE PRACTICE LAB')+`<div class="tabs"><button class="tab ${practiceType==='problems'?'active':''}" data-action="practice-tab" data-tab="problems">LeetCode · Java <span class="track-count">${problems.length}</span></button><button class="tab ${practiceType==='questions'?'active':''}" data-action="practice-tab" data-tab="questions">Knowledge checks <span class="track-count">${questions.length}</span></button></div><div class="toolbar"><input id="practice-search" type="search" placeholder="Search questions or topics…" aria-label="Search practice questions"><select id="practice-filter" aria-label="Filter practice status"><option value="all">All statuses</option>${Object.entries(exerciseStatuses).map(([s,l])=>`<option value="${s}" ${param===s?'selected':''}>${l}</option>`).join('')}</select>${practiceType==='problems'?`<select id="difficulty-filter" aria-label="Filter difficulty"><option value="all">All difficulties</option><option>Easy</option><option>Medium</option><option>Hard</option></select>`:`<select id="practice-track" aria-label="Filter knowledge check track"><option value="all">All learning paths</option>${TRACKS.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select>`}</div><div id="practice-results">${practiceResults('',param)}</div>`;}
function practiceResults(query='',filter='all',difficulty='all',track='all'){const list=(practiceType==='problems'?problems:questions).filter(p=>(filter==='all'||exerciseOf(p.id).status===filter)&&(difficulty==='all'||p.difficulty===difficulty)&&(track==='all'||p.track===track)&&(p.title+' '+(p.number||'')+' '+topicMap.get(p.topicId).title).toLowerCase().includes(query.toLowerCase()));if(!list.length)return empty('search','No questions match','Try another search or reset your filters.');return `<p class="muted" style="font-size:10px">${list.length} questions · ${list.filter(p=>exerciseOf(p.id).status==='completed').length} completed</p>`+(practiceType==='problems'?problemTable(list,true):list.map(q=>`<div class="question-card"><a href="#topic/${q.topicId}" class="topic-link">${escapeHTML(topicMap.get(q.topicId).title)} ↗</a><h3 style="margin-top:10px">${escapeHTML(q.title)}</h3><details><summary>Reveal explanation</summary><p>${escapeHTML(q.answer)}</p></details>${exerciseControls(q.id)}</div>`).join(''));}
function notesPage(){return pageHead('Your second memory.','The explanations that clicked, the questions that lingered, and the connections you made.','MY NOTEBOOK',`<button class="button primary" data-action="new-note" data-scope="workspace">${icon('plus')}New note</button>`)+`<div class="toolbar"><input id="notes-search" type="search" placeholder="Find something you wrote…" aria-label="Search notes"><select id="notes-track" aria-label="Filter notes by path"><option value="all">All notes</option><option value="workspace">Workspace notes</option>${TRACKS.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select><button class="view-filter" id="pinned-filter" data-action="pinned-filter" aria-pressed="false">${icon('pin')}Pinned only</button></div><div id="notes-results">${notesResults()}</div>`;}
function notesResults(query='',track='all',pinned=false){const list=sortedNotes(visibleNotes().filter(n=>(!pinned||n.pinned)&&(track==='all'||(track==='workspace'?n.scope==='workspace':scopeTrack(n.scope)===track))&&(n.title+' '+n.body+' '+scopeName(n.scope)).toLowerCase().includes(query.toLowerCase())));return list.length?`<div class="notes-grid">${list.map(noteCard).join('')}</div>`:empty('note','A fresh page for your thoughts','Add notes to a path, module, topic, checkpoint, or question. They all come together here.');}
function reviewPage(){const ts=topics.filter(t=>statusOf(t.id)==='revisit'),ps=[...exerciseMap.values()].filter(p=>['issue','revisit'].includes(exerciseOf(p.id).status));return pageHead('Come back with fresh eyes.','Everything you marked to revisit, or could use a little more time with.','THE REVISIT QUEUE')+(!ts.length&&!ps.length?empty('review','Nothing waiting for a second look','Mark a topic “Revisit later” or a question “Having an issue” to collect it here.'):ts.map(t=>`<div class="review-item">${icon('book')}<div class="grow"><strong>${escapeHTML(t.title)}</strong><small>${trackMap.get(t.track).title} · Topic</small></div>${badge('revisit')}<a href="#topic/${t.id}" class="button">Return to topic${icon('arrow')}</a></div>`).join('')+ps.map(p=>`<div class="review-item">${icon(p.url?'code':'flag')}<div class="grow"><strong>${escapeHTML(p.title)}</strong><small>${escapeHTML(topicMap.get(p.topicId).title)} · ${exerciseOf(p.id).attempts} attempts</small></div>${exerciseSelect(p.id,exerciseOf(p.id))}<a href="#topic/${p.topicId}" class="button">Study again${icon('arrow')}</a></div>`).join(''));}
function library(){return pageHead('Good ideas have good roots.','Your reading companions, organized by learning path. Go deeper whenever you’re ready.','THE BOOKSHELF')+`<div class="notice">This roadmap consolidates public topic outlines into an original, practical curriculum. It is not a reproduction of the books or an exhaustive transcription of every heading. Lessons are concise study guides; the books provide fuller explanations. Source pages were reviewed September 2026. Framework APIs and Oracle features should be checked against the version you use.</div>`+TRACKS.map(t=>`<div class="section-heading"><h2>${icon(t.icon)} ${t.title}</h2><a href="#track/${t.id}" class="button subtle">Open learning path${icon('arrow')}</a></div><div class="sources-grid">${Object.keys(BOOKS).filter(k=>BOOKS[k].track===t.id).map(sourceCard).join('')}</div>`).join('');}
function heatmap(){const start=new Date();start.setHours(12,0,0,0);start.setDate(start.getDate()-((start.getDay()+6)%7)-84);let cells='';for(let w=0;w<13;w++){let week='';for(let d=0;d<7;d++){const day=new Date(start);day.setDate(day.getDate()+w*7+d);const key=localDate(day),count=state.activity[key]||0;week+=`<span class="heat-cell level${Math.min(4,count)}" title="${key}: ${count} learning activities" aria-label="${key}: ${count} learning activities"></span>`;}cells+=`<div class="heat-week">${week}</div>`;}return `<div class="heatmap"><div class="heat-labels"><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span><span>S</span></div>${cells}</div>`;}
function progressPage(){return pageHead('Look how far you’ve come.','Progress is the understanding you keep. Every concept, attempt, and note adds up.','MY PROGRESS')+stats()+`<div class="activity-panel"><div class="row"><h3>Your last 13 weeks</h3><small style="font-size:10px">Activity from studying, practice, and note taking</small></div>${heatmap()}<p class="muted" style="font-size:10px;margin:10px 0 0">More color means more recorded learning actions. Empty days are simply room to begin again.</p></div><div class="section-heading"><h2>A little further in every path</h2><button class="button" data-action="goal">${icon('target')}Set weekly intention</button></div>${TRACKS.map(t=>`<div class="progress-track-row"><span><a href="#track/${t.id}">${t.title}</a></span>${progressBar(percent(trackTopics(t)),t.color)}<strong>${percent(trackTopics(t))}%</strong><small>${completed(trackTopics(t))} / ${trackTopics(t).length} completed</small></div>`).join('')}<div class="section-heading"><h2>Beyond the checkmarks</h2></div><div class="progress-breakdown"><div class="mini-stat"><strong>${Object.values(state.checks).filter(Boolean).length}</strong><small>Concept checkpoints understood</small></div><div class="mini-stat"><strong>${questions.filter(q=>exerciseOf(q.id).status==='completed').length}</strong><small>Knowledge checks completed</small></div><div class="mini-stat"><strong>${Object.values(state.exercises).reduce((n,p)=>n+p.attempts,0)}</strong><small>Practice attempts recorded</small></div></div>${notesSection('workspace','Workspace reflections')}`;}
function setBreadcrumb(){const {parts}=route();let label='Overview';if(parts[0]==='track')label=trackMap.get(parts[1])?.title||'Learning path';else if(parts[0]==='topic'){const t=topicMap.get(parts[1]);label=t?`<a href="#track/${t.track}">${trackMap.get(t.track).title}</a> <span> / </span> <span class="current">Topic</span>`:'Topic';}else label=({practice:'Practice lab',notes:'My notes',review:'Revisit queue',library:'Books & resources',progress:'My progress'})[parts[0]]||label;$('#breadcrumbs').innerHTML=`<a href="#overview">My workspace</a> <span style="margin:0 9px;color:#c0c5b8">/</span> <span class="current">${label}</span>`;}
function render(preserveScroll=false){const y=scrollY,{parts}=route();const trackView=preserveScroll&&$('#track-search')?{query:$('#track-search').value,filter:$('#track-status').value,open:[...document.querySelectorAll('.module[open] summary strong')].map(e=>e.textContent)}:null;sidebar();setBreadcrumb();let html;switch(parts[0]){case 'track':html=trackMap.has(parts[1])?trackPage(trackMap.get(parts[1])):null;break;case 'topic':html=topicMap.has(parts[1])?topicPage(topicMap.get(parts[1])):null;break;case 'practice':html=practice();break;case 'notes':html=notesPage();break;case 'review':html=reviewPage();break;case 'library':html=library();break;case 'progress':html=progressPage();break;default:html=overview();}$('#main').innerHTML=html||empty('book','This page isn’t in your workspace','Use the sidebar to open a learning path.');if(trackView&&$('#track-search')){$('#track-search').value=trackView.query;$('#track-status').value=trackView.filter;refreshModules();document.querySelectorAll('.module').forEach(m=>m.open=trackView.open.includes($('summary strong',m).textContent));}syncMobileNav();document.title=(parts[0]==='topic'?topicMap.get(parts[1])?.title:parts[0]==='track'?trackMap.get(parts[1])?.title:'Your learning workspace')+' · Commonplace';if(preserveScroll)scrollTo(0,y);else scrollTo(0,0);}
function syncMobileNav(){const mobile=matchMedia('(max-width:700px)').matches,open=$('#sidebar').classList.contains('open');$('#sidebar').inert=mobile&&!open;$('.mobile-menu').setAttribute('aria-expanded',String(open));}
function refreshPractice(){if($('#practice-results'))$('#practice-results').innerHTML=practiceResults($('#practice-search').value,$('#practice-filter').value,$('#difficulty-filter')?.value||'all',$('#practice-track')?.value||'all');}
function refreshNotes(){if($('#notes-results'))$('#notes-results').innerHTML=notesResults($('#notes-search').value,$('#notes-track').value,$('#pinned-filter').getAttribute('aria-pressed')==='true');}
function refreshModules(){if($('#module-list'))$('#module-list').innerHTML=moduleList(trackMap.get(route().parts[1]),$('#track-search').value,$('#track-status').value);}
function setTopic(id,status){if(!topicMap.has(id)||!own(statuses,status))return;state.topics[id]={status,updated:new Date().toISOString()};if(status==='completed'||status==='new')topicMap.get(id).parts.forEach((p,i)=>state.checks[id+'-p'+i]=status==='completed');recordActivity();save();render(true);}
function setExercise(id,patch){if(!exerciseMap.has(id))return;state.exercises[id]={...exerciseOf(id),...patch};recordActivity();save();sidebar();}
function openModal(content){returnFocus=document.activeElement;const d=$('#modal');if(d.open)d.close();d.innerHTML=content;d.showModal();}
function modalShell(title,content,footer=''){return `<div class="modal-head"><h2 id="modal-title">${escapeHTML(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;}
function closeModal(){flushNote();$('#modal').close();noteDraft=null;render(true);returnFocus?.isConnected&&returnFocus.focus();}
function scopeOptions(selected){const all=[['workspace','Workspace / General notes'],...TRACKS.map(t=>[t.id,t.title+' / Section notes']),...TRACKS.flatMap(t=>t.modules.map(m=>[m.id,t.title+' / '+m.title])),...topics.map(t=>[t.id,trackMap.get(t.track).title+' / '+t.title])];if(!all.some(([id])=>id===selected))all.push([selected,scopeName(selected)]);return all.map(([id,title])=>`<option value="${id}" ${id===selected?'selected':''}>${escapeHTML(title)}</option>`).join('');}
function openNote(scope='workspace',id=null){flushNote();const existing=id?state.notes.find(n=>n.id===id):null;noteDraft=existing?{...existing}:{id:'n-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),scope:validScope(scope)?scope:'workspace',title:'',body:'',color:'yellow',pinned:false,updated:new Date().toISOString()};noteRecorded=false;
 openModal(modalShell(existing?'Your note':'Make a little space for an idea',`<label for="note-scope">Keep this note with</label><select id="note-scope">${scopeOptions(noteDraft.scope)}</select><label for="note-title">Title</label><input id="note-title" type="text" maxlength="200" placeholder="The idea I want to remember…" value="${escapeHTML(noteDraft.title)}"><div class="note-toolbar"><button data-action="note-format" data-format="bullet" aria-label="Insert bullet point">• Bullet</button><button data-action="note-format" data-format="check" aria-label="Insert checklist item">☐ Checklist</button><button data-action="note-format" data-format="bold" aria-label="Make selected text bold"><strong>B</strong></button><div class="color-picker">${colors.map(c=>`<button class="color-swatch ${c} ${c===noteDraft.color?'selected':''}" data-action="note-color" data-color="${c}" aria-label="${c} note" aria-pressed="${c===noteDraft.color}"></button>`).join('')}</div></div><label class="skip-label" for="note-body">Notes</label><textarea id="note-body" maxlength="50000" placeholder="Explain it in your own words. Add an example, bullet points, or a question for later…">${escapeHTML(noteDraft.body)}</textarea>`,`<small id="note-save-status">${saveFailed?'Browser saving is unavailable':'Changes save automatically'}</small>${existing?`<button class="button danger" data-action="delete-note" data-id="${existing.id}">${icon('trash')}Delete</button>`:''}<button class="button primary" data-action="close-modal">Done${icon('check')}</button>`));$('#note-title').focus();
}
function flushNote(){if(!noteDraft||!$('#note-title'))return;const prev=state.notes.find(n=>n.id===noteDraft.id);noteDraft.title=$('#note-title').value;noteDraft.body=$('#note-body').value;noteDraft.scope=$('#note-scope').value;if(!noteDraft.title.trim()&&!noteDraft.body.trim()&&!prev)return;const changed=!prev||['title','body','scope','color','pinned'].some(k=>prev[k]!==noteDraft[k]);if(!changed)return;noteDraft.updated=new Date().toISOString();const index=state.notes.findIndex(n=>n.id===noteDraft.id);if(index>=0)state.notes[index]={...noteDraft};else state.notes.push({...noteDraft});if(!noteRecorded){recordActivity();noteRecorded=true;}save();if($('#note-save-status'))$('#note-save-status').textContent=saveFailed?'Not saved — export a backup':'Saved to this browser';sidebar();}
function scopeNotes(scope){const list=sortedNotes(visibleNotes().filter(n=>n.scope===scope));if(!list.length){openNote(scope);return;}noteDraft=null;openModal(modalShell('Notes · '+scopeName(scope),`<div class="notes-grid" style="grid-template-columns:1fr">${list.map(noteCard).join('')}</div>`,`<button class="button primary" data-action="new-note" data-scope="${scope}">${icon('plus')}Add another note</button>`));}
function openSearch(){noteDraft=null;openModal(`<div class="search-input-wrap">${icon('search')}<label id="modal-title" class="skip-link" for="global-search">Search your workspace</label><input id="global-search" type="search" placeholder="Find a topic, concept, problem, or note…" autocomplete="off"><button class="icon-button" data-action="close-modal" aria-label="Close search">${icon('close')}</button></div><div class="search-results" id="search-results"><p class="search-empty">Your entire learning workspace, one search away.</p></div>`);$('#global-search').focus();}
function search(query){const q=query.trim().toLowerCase();if(!q){$('#search-results').innerHTML='<p class="search-empty">Try “attention”, “sliding window”, or something from your notes.</p>';return;}const matches=[...topics.filter(t=>(t.title+' '+t.summary+' '+t.parts.map(p=>p.title+' '+p.detail).join(' ')).toLowerCase().includes(q)).map(t=>({title:t.title,label:trackMap.get(t.track).title+' · Topic',route:'#topic/'+t.id,icon:trackMap.get(t.track).icon})),...problems.filter(p=>(p.number+' '+p.title).toLowerCase().includes(q)).map(p=>({title:p.title,label:'LeetCode '+p.number+' · Practice',route:'#topic/'+p.topicId,icon:'code'})),...visibleNotes().filter(n=>(n.title+' '+n.body).toLowerCase().includes(q)).map(n=>({title:n.title||'Untitled note',label:'Note · '+scopeName(n.scope),note:n.id,icon:'note'}))].slice(0,35);$('#search-results').innerHTML=matches.length?matches.map(m=>`<button class="search-result" ${m.note?`data-action="edit-note" data-id="${m.note}"`:`data-search-nav="${m.route}"`}>${icon(m.icon)}<span><strong>${escapeHTML(m.title)}</strong><small>${escapeHTML(m.label)}</small></span>${icon('arrow')}</button>`).join(''):'<p class="search-empty">No matches. Try a broader phrase.</p>';}
function exportBackup(){flushNote();const payload=JSON.stringify(state,null,2),blob=new Blob([payload],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='commonplace-backup-'+localDate()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded. Keep it somewhere safe.');}
let pendingImport=null;
async function importBackup(file){if(!file)return;if(file.size>5*1024*1024){toast('That file is too large. Backups must be under 5 MB.');return;}try{pendingImport=validateState(JSON.parse(await file.text()));noteDraft=null;openModal(modalShell('Restore this workspace?',`<p style="font-size:13px">This backup contains <strong>${Object.keys(pendingImport.topics).length} topic records</strong>, <strong>${Object.keys(pendingImport.exercises).length} practice records</strong>, and <strong>${pendingImport.notes.length} notes</strong>.</p><p class="muted" style="font-size:12px">Restoring replaces progress and notes currently in this browser. Download your current backup first if you want to keep both versions.</p>`,`<button class="button" data-action="export">Export current backup</button><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-import">Restore backup</button>`));}catch(error){pendingImport=null;toast(error.message||'Unable to read this backup. Your workspace is unchanged.');}}
document.addEventListener('click',async event=>{
 if(event.target.closest('a.skip-link')){event.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}
 if($('#sidebar').classList.contains('open')&&!event.target.closest('#sidebar,[data-action="menu"]')){$('#sidebar').classList.remove('open');syncMobileNav();}
 const scrollLink=event.target.closest('[data-scroll]');if(scrollLink){event.preventDefault();document.getElementById(scrollLink.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
 const nav=event.target.closest('[data-nav]');if(nav){trackTab='curriculum';navigate(nav.dataset.nav);return;}
 const searchNav=event.target.closest('[data-search-nav]');if(searchNav){$('#modal').close();navigate(searchNav.dataset.searchNav);return;}
 const el=event.target.closest('[data-action]');if(!el)return;const {action,id,scope}=el.dataset;
 switch(action){
 case 'menu':$('#sidebar').classList.toggle('open');syncMobileNav();break;
 case 'search':openSearch();break;
 case 'close-modal':closeModal();break;
 case 'new-note':openNote(scope);break;
 case 'edit-note':openNote('workspace',id);break;
 case 'scope-notes':scopeNotes(scope);break;
 case 'pin-note':{const n=state.notes.find(n=>n.id===id);if(n){n.pinned=!n.pinned;save();if($('#modal').open&&!noteDraft)scopeNotes(n.scope);else if(route().parts[0]==='notes')refreshNotes();else render(true);}break;}
 case 'delete-note':{flushNote();noteDraft=null;openModal(modalShell('Delete this note?',`<p style="font-size:13px">This removes “${escapeHTML(state.notes.find(n=>n.id===id)?.title||'Untitled note')}” from this browser. Export a backup first if you want to keep a copy.</p>`,`<button class="button" data-action="edit-note" data-id="${id}">Keep note</button><button class="button danger" data-action="confirm-delete" data-id="${id}">Delete note</button>`));break;}
 case 'confirm-delete':state.notes=state.notes.filter(n=>n.id!==id);save();$('#modal').close();render(true);toast('Note deleted.');break;
 case 'note-color':if(noteDraft){noteDraft.color=el.dataset.color;document.querySelectorAll('.color-swatch').forEach(b=>{b.classList.toggle('selected',b.dataset.color===noteDraft.color);b.setAttribute('aria-pressed',String(b.dataset.color===noteDraft.color));});flushNote();}break;
 case 'note-format':{const text=$('#note-body'),start=text.selectionStart,end=text.selectionEnd,selected=text.value.slice(start,end);const insert=el.dataset.format==='bold'?`**${selected||'important idea'}**`:(start&&text.value[start-1]!=='\n'?'\n':'')+(el.dataset.format==='check'?'[ ] ':'- ')+selected;text.setRangeText(insert,start,end,'end');text.focus();flushNote();break;}
 case 'complete-topic':setTopic(id,statusOf(id)==='completed'?'learning':'completed');toast(statusOf(id)==='completed'?'One more idea understood. Nice work.':'Topic moved back to learning.');break;
 case 'track-tab':trackTab=el.dataset.tab;render(true);break;
 case 'practice-tab':practiceType=el.dataset.tab;render(true);break;
 case 'attempt':{const value=Math.max(0,Math.min(9999,exerciseOf(id).attempts+Number(el.dataset.delta)));if(value!==exerciseOf(id).attempts)setExercise(id,{attempts:value});document.querySelectorAll('[data-attempts]').forEach(input=>{if(input.dataset.attempts===id)input.value=value;});break;}
 case 'pinned-filter':el.setAttribute('aria-pressed',el.getAttribute('aria-pressed')!=='true'?'true':'false');el.classList.toggle('active');refreshNotes();break;
 case 'copy-example':{const text=topicMap.get(id)?.example.code;try{await navigator.clipboard.writeText(text);toast('Example copied.');}catch{const field=document.createElement('textarea');field.value=text;document.body.append(field);field.select();const ok=document.execCommand('copy');field.remove();toast(ok?'Example copied.':'Select the example text to copy it.');}break;}
 case 'export':exportBackup();break;
 case 'import':$('#import-file').click();break;
 case 'confirm-import':if(pendingImport){state=pendingImport;pendingImport=null;saveFailed=false;$('#storage-warning').hidden=true;try{observedStorage=localStorage.getItem(KEY);}catch{}save();$('#modal').close();render();toast(saveFailed?'Restored in memory; export before closing.':'Workspace restored successfully.');}break;
 case 'goal':noteDraft=null;openModal(modalShell('Make a weekly intention','<p class="muted" style="font-size:12px">Choose a realistic number of topics to understand this week. Weeks begin on Monday. You can change this whenever life changes.</p><label for="weekly-goal">Topics per week</label><input id="weekly-goal" type="number" min="1" max="50" step="1" value="'+state.goal+'">','<button class="button primary" data-action="save-goal">Save intention</button>'));break;
 case 'save-goal':{const n=Number($('#weekly-goal').value);if(!Number.isInteger(n)||n<1||n>50){$('#weekly-goal').setCustomValidity('Choose a whole number from 1 to 50.');$('#weekly-goal').reportValidity();break;}state.goal=n;save();closeModal();toast('Weekly intention updated.');break;}
 }
});
document.addEventListener('change',event=>{const el=event.target;
 if(el.matches('[data-topic-toggle]')){setTopic(el.dataset.topicToggle,el.checked?'completed':'new');return;}
 if(el.matches('[data-topic-status]')){setTopic(el.dataset.topicStatus,el.value);return;}
 if(el.matches('[data-check]')){const key=el.dataset.check,id=checkpointParent(key),t=topicMap.get(id);state.checks[key]=el.checked;const all=t.parts.every((p,i)=>state.checks[id+'-p'+i]);state.topics[id]={status:all?'completed':'learning',updated:new Date().toISOString()};recordActivity();save();render(true);return;}
 if(el.matches('[data-exercise]')){const id=el.dataset.exercise;if(own(exerciseStatuses,el.value))setExercise(id,{status:el.value});if(route().parts[0]==='review')render(true);else if(route().parts[0]==='practice')refreshPractice();return;}
 if(el.matches('[data-attempts]')){const parsed=Number(el.value);const n=Number.isFinite(parsed)?Math.max(0,Math.min(9999,Math.trunc(parsed))):0;el.value=n;setExercise(el.dataset.attempts,{attempts:n});return;}
 if(['practice-filter','difficulty-filter','practice-track'].includes(el.id))refreshPractice();
 if(el.id==='notes-track')refreshNotes();
 if(el.id==='track-status')refreshModules();
 if(el.id==='note-scope')flushNote();
 if(el.id==='import-file'){importBackup(el.files[0]);el.value='';}
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search')search(el.value);if(el.id==='practice-search')refreshPractice();if(el.id==='notes-search')refreshNotes();if(el.id==='track-search')refreshModules();if(el.id==='note-title'||el.id==='note-body')flushNote();if(el.id==='weekly-goal')el.setCustomValidity('');});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();flushNote();openSearch();}if(event.key==='Escape'){$('#sidebar').classList.remove('open');syncMobileNav();}});
$('#modal').addEventListener('cancel',()=>{flushNote();noteDraft=null;setTimeout(()=>render(true),0);});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{flushNote();if($('#modal').open)$('#modal').close();noteDraft=null;$('#sidebar').classList.remove('open');const {parts}=route();if(parts[0]==='topic'&&topicMap.has(parts[1])){state.lastTopic=parts[1];save();}if(parts[0]!=='track')trackTab='curriculum';render();});
window.addEventListener('storage',event=>{if(event.key!==KEY)return;if($('#modal').open||saveFailed){saveFailed=true;showStorageWarning('This workspace changed in another tab. Export your current work before refreshing. Saving is paused to protect both versions.');$('#save-indicator').textContent='Changes are not saved';return;}try{if(!event.newValue){saveFailed=true;showStorageWarning('Saved workspace data was removed in another tab. Export this tab’s work before refreshing.');return;}state=validateState(JSON.parse(event.newValue));observedStorage=event.newValue;render(true);toast('Workspace updated from another tab.');}catch{toast('A change from another tab could not be loaded.');}});
window.addEventListener('resize',syncMobileNav);
window.addEventListener('beforeunload',()=>flushNote());
window.Commonplace={topics,problems,questions,validateState,blankState,escapeHTML,getState:()=>JSON.parse(JSON.stringify(state)),storageKey:KEY};
render();
if(saveFailed)$('#save-indicator').textContent='Changes are not saved';
})();
